# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require "rake"

RSpec.describe "timekeeping:alerts" do
  it "logs a reference_unavailable alert with company_id read from the metrics endpoint with the service token" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!

    token = SecureRandom.hex(16)
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token

    previous = Time.current.to_i - 300
    window_start = Time.at(previous - (previous % 300)).utc.iso8601
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000], "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [{ "company_id" => 7, "windows" => [{
        "window_start" => window_start, "writes" => 97, "reference_unavailable" => 3, "stale_generation" => 0,
        "latency_ms_sum" => 1000, "latency_ms_buckets" => { "25" => 100 }
      }] }]
    }
    metrics = stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{token}" })
      .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

    # "It logs each alert with `company_id`."
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      Rake::Task["timekeeping:alerts"].invoke
    ensure
      $stdout = original_stdout
    end

    expect(metrics).to have_been_requested.once
    expect(output.string).to match(/alert=reference_unavailable company_id=7\b/)
    expect(output.string.scan(/alert=reference_unavailable/).size).to eq(1)
    expect(output.string).not_to include(token)
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before&.dig(key) }
  end
end

RSpec.describe "timekeeping:alerts" do
  it "exits non-zero and never reports no alerts when the metrics endpoint refuses the token" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!

    token = SecureRandom.hex(16)
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .to_return(status: 401, body: JSON.generate(reason: "unauthorized"))

    expect { Rake::Task["timekeeping:alerts"].invoke }
      .to raise_error(SystemExit) { |error| expect(error.status).not_to eq(0) }
      .and output(satisfy { |stdout| !stdout.include?("no alerts") && !stdout.include?(token) }).to_stdout
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before&.dig(key) }
  end
end
